    // In a real Eclipse environment, org.eclipse.search.internal.ui.SearchPlugin would be available.
    static class SearchPlugin {
        public static SearchPlugin getDefault() { return new SearchPlugin(); }
        public IWorkbench getWorkbench() { return PlatformUI.getWorkbench(); } // Dummy implementation
